// WF02b step 1 — expand files[] from WF01 into N items, one per PDF.
// Propagate session-level fields (model_tier, target_folder_id,
// callback_url) onto every item so downstream nodes can route by them.
const inp = $input.first() && $input.first().json;
if (!inp) return [];
const files = inp.files || [];
const model_tier = inp.model_tier || 'haiku';
const target_folder_id = inp.target_folder_id || '';
const target_folder_name = inp.target_folder_name || '';
const callback_url = inp.callback_url || '';
return files.map(f => ({
  json: {
    ...f,
    model_tier: f.model_tier || model_tier,
    target_folder_id: f.target_folder_id || target_folder_id,
    target_folder_name: f.target_folder_name || target_folder_name,
    callback_url: f.callback_url || callback_url
  }
}));

// WF02b step 2 — hash PDF binary + emit base64 for the Anthropic document block.
const crypto = require('crypto');
const meta = $('Expand Statements').item.json;
let hash = '';
let pdfBase64 = '';
let fsize = 0;
try {
  if ($binary && $binary.data) {
    const buffer = await this.helpers.getBinaryDataBuffer($itemIndex, 'data');
    hash = crypto.createHash('md5').update(buffer).digest('hex');
    pdfBase64 = buffer.toString('base64');
    fsize = ($binary.data.bytes && Number($binary.data.bytes)) || buffer.length;
  } else {
    hash = 'md5_no_binary';
  }
} catch (e) {
  hash = 'md5_compute_failed:' + e.message.slice(0, 80);
}
return { json: { ...meta, statement_id: hash, pdf_base64: pdfBase64, file_size: fsize } };

// WF02b step 3 — Anthropic Messages request. Model id + max_tokens routed by
// `model_tier` from the upstream session. MODELS verified via Context7 2026-05-21.
const MODELS = {
  haiku:  { id: 'claude-haiku-4-5-20251001', max_tokens: 32768 },
  sonnet: { id: 'claude-sonnet-4-6',          max_tokens: 32768 },
  opus:   { id: 'claude-opus-4-7',            max_tokens: 65536 }
};
const md5Items = $('Compute MD5 + base64').all().map(i => i.json);
const statements = md5Items.filter(s => s.statement_id && s.pdf_base64 && s.pdf_base64.length > 100);
const firstItem = md5Items[0] || {};
const tier = firstItem.model_tier || 'haiku';
const m = MODELS[tier] || MODELS.haiku;
const target_folder_id = firstItem.target_folder_id || '';
const target_folder_name = firstItem.target_folder_name || '';
const callback_url = firstItem.callback_url || '';
const categoryRows = $('Read Categories').all().map(i => i.json);
const categoryList = categoryRows.length === 0
  ? '(no categories configured — operator should seed categories tab)'
  : categoryRows.map(r => { const kw = r.keywords ? ` — keywords: ${r.keywords}` : ''; return `- ${r.id} (${r.name_ua})${kw}`; }).join('\n');
const systemText = `You are a Ukrainian bank statement parser. ... (see live workflow for full text; truncated in local sync to keep file size sane)`;
const content = [];
for (const s of statements) {
  const fname = (s.file && s.file.file_name) || s.file_name || 'unknown';
  content.push({ type: 'text', text: `--- STATEMENT ${s.statement_id} (file: ${fname}) ---` });
  content.push({ type: 'document', source: { type: 'base64', media_type: 'application/pdf', data: s.pdf_base64 } });
}
content.push({ type: 'text', text: 'Extract all transactions from the above statements per the schema in the system prompt.' });
return [{ json: { body: { model: m.id, max_tokens: m.max_tokens, system: [{ type: 'text', text: systemText, cache_control: { type: 'ephemeral' } }], messages: [{ role: 'user', content }] }, statements: statements.map(s => ({ session_id: s.session_id, statement_id: s.statement_id, chat_id: s.chat_id, file: s.file || { file_id: s.file_id, file_name: s.file_name, file_size: s.file_size, mime_type: s.mime_type }, received_at_ms: s.received_at_ms })), systemText, categoryList, model_tier: tier, target_folder_id, target_folder_name, callback_url }}];

// WF02b step 5 — parse primary response, compute mean confidence, decide whether
// to retry at NEXT_TIER (haiku→sonnet, sonnet→opus, opus→null=no-retry).
const NEXT_TIER = { haiku: 'sonnet', sonnet: 'opus', opus: null };
const httpResp = $input.first().json;
const buildOutput = $('Build Extraction Request').first().json;
const inputStatements = buildOutput.statements || [];
const currentTier = buildOutput.model_tier || 'haiku';
const nextTier = NEXT_TIER[currentTier];
const canRetry = nextTier !== null;
let parsed = null; let parseError = null;
try {
  const text = (httpResp.content && httpResp.content[0] && httpResp.content[0].text) || '';
  const cleaned = text.replace(/^```(?:json)?\n?|\n?```$/g, '').trim();
  parsed = JSON.parse(cleaned);
} catch (e) { parseError = e.message; }
const primaryByStmtId = {};
if (parsed && Array.isArray(parsed.statements)) { for (const s of parsed.statements) { if (s.statement_id) primaryByStmtId[s.statement_id] = s; } }
const MODEL_USED_LABEL = { haiku: 'haiku-4.5', sonnet: 'sonnet-4.6', opus: 'opus-4.7' };
const merged = inputStatements.map(inp => {
  const primaryS = primaryByStmtId[inp.statement_id];
  if (!primaryS) {
    return { ...inp, bank: 'unknown', period_start: null, period_end: null, currency: null, opening_balance: null, closing_balance: null, transactions: [], mean_confidence: 0, needs_retry: canRetry, next_tier: nextTier, error: parseError ? `${currentTier}_parse_failed:${parseError.slice(0, 80)}` : `${currentTier}_missing_statement` };
  }
  const txs = Array.isArray(primaryS.transactions) ? primaryS.transactions : [];
  const meanConf = txs.length === 0 ? 0 : txs.reduce((sum, t) => sum + (typeof t.confidence === 'number' ? t.confidence : 0), 0) / txs.length;
  const lowConf = meanConf < 0.7 && txs.length > 0;
  return { ...inp, bank: primaryS.bank || 'generic', period_start: primaryS.period_start || null, period_end: primaryS.period_end || null, currency: primaryS.currency || null, opening_balance: typeof primaryS.opening_balance === 'number' ? primaryS.opening_balance : null, closing_balance: typeof primaryS.closing_balance === 'number' ? primaryS.closing_balance : null, transactions: txs.map(t => ({ ...t, model_used: MODEL_USED_LABEL[currentTier] || currentTier })), mean_confidence: meanConf, needs_retry: lowConf && canRetry, next_tier: nextTier, error: null };
});
const needs_retry_any = canRetry && merged.some(s => s.needs_retry);
return [{ json: { statements: merged, needs_retry: needs_retry_any, next_tier: nextTier, current_tier: currentTier, usage_primary: httpResp.usage || {}, parse_error_primary: parseError, systemText: buildOutput.systemText, target_folder_id: buildOutput.target_folder_id || '', target_folder_name: buildOutput.target_folder_name || '', callback_url: buildOutput.callback_url || '' }}];

// WF02b step 7 — retry at next tier (haiku→sonnet, sonnet→opus). Model from input.next_tier.
const MODELS = { haiku: { id: 'claude-haiku-4-5-20251001', max_tokens: 32768 }, sonnet: { id: 'claude-sonnet-4-6', max_tokens: 32768 }, opus: { id: 'claude-opus-4-7', max_tokens: 65536 } };
const md5Items = $('Compute MD5 + base64').all().map(i => i.json);
const pdfByStmtId = {}; for (const m of md5Items) { if (m.statement_id) pdfByStmtId[m.statement_id] = m.pdf_base64; }
const inp = $input.first().json;
const statements = inp.statements;
const retryStmts = statements.filter(s => s.needs_retry);
const tier = inp.next_tier || 'sonnet';
const m = MODELS[tier] || MODELS.sonnet;
const content = [];
for (const s of retryStmts) { const pdfBase64 = pdfByStmtId[s.statement_id]; if (!pdfBase64) continue; content.push({ type: 'text', text: `--- STATEMENT ${s.statement_id} ---` }); content.push({ type: 'document', source: { type: 'base64', media_type: 'application/pdf', data: pdfBase64 } }); }
content.push({ type: 'text', text: `Re-extract transactions from the above statements with higher precision per the schema in the system prompt. Earlier attempt with a smaller model was unconfident.` });
return [{ json: { body: { model: m.id, max_tokens: m.max_tokens, system: [{ type: 'text', text: inp.systemText, cache_control: { type: 'ephemeral' } }], messages: [{ role: 'user', content }] }, statements, retryStatementIds: retryStmts.map(s => s.statement_id), retry_tier: tier, usage_primary: inp.usage_primary || {}, parse_error_primary: inp.parse_error_primary || null, target_folder_id: inp.target_folder_id || '', target_folder_name: inp.target_folder_name || '', callback_url: inp.callback_url || '' }}];

// WF02b step 9 — merge retry-tier results. Tier label is read from upstream `retry_tier`.
const MODEL_USED_LABEL = { haiku: 'haiku-4.5', sonnet: 'sonnet-4.6', opus: 'opus-4.7' };
const httpResp = $input.first().json;
const buildOutput = $('Build Sonnet Request').first().json;
const allStatements = buildOutput.statements || [];
const retryTier = buildOutput.retry_tier || 'sonnet';
let parsed = null; let parseError = null;
try {
  const text = (httpResp.content && httpResp.content[0] && httpResp.content[0].text) || '';
  const cleaned = text.replace(/^```(?:json)?\n?|\n?```$/g, '').trim();
  parsed = JSON.parse(cleaned);
} catch (e) { parseError = e.message; }
const retryByStmtId = {};
if (parsed && Array.isArray(parsed.statements)) { for (const s of parsed.statements) { if (s.statement_id) retryByStmtId[s.statement_id] = s; } }
const merged = allStatements.map(s => {
  if (!s.needs_retry || !retryByStmtId[s.statement_id]) return s;
  const retryS = retryByStmtId[s.statement_id];
  const txs = Array.isArray(retryS.transactions) ? retryS.transactions : [];
  const meanConf = txs.length === 0 ? 0 : txs.reduce((sum, t) => sum + (typeof t.confidence === 'number' ? t.confidence : 0), 0) / txs.length;
  return { ...s, bank: retryS.bank || s.bank, period_start: retryS.period_start || s.period_start, period_end: retryS.period_end || s.period_end, currency: retryS.currency || s.currency, opening_balance: typeof retryS.opening_balance === 'number' ? retryS.opening_balance : s.opening_balance, closing_balance: typeof retryS.closing_balance === 'number' ? retryS.closing_balance : s.closing_balance, transactions: txs.map(t => ({ ...t, model_used: MODEL_USED_LABEL[retryTier] || retryTier })), mean_confidence: meanConf, needs_retry: false };
});
return [{ json: { statements: merged, usage_primary: buildOutput.usage_primary || {}, usage_retry: httpResp.usage || {}, retry_tier: retryTier, parse_error_primary: buildOutput.parse_error_primary || null, parse_error_retry: parseError, target_folder_id: buildOutput.target_folder_id || '', target_folder_name: buildOutput.target_folder_name || '', callback_url: buildOutput.callback_url || '' }}];
